    },
    {
      "@id": "entity:source-curriculumImportPage.description",
      "@type": "prov:Entity",
      "prov:value": "Upload a PDF or CSV of official state academic standards (TEKS, NGSS, Common Core, etc.). Ollama extracts each standard for review. Once saved as a global set, all teachers and homeschool parents can map their activities against these standards. Re-uploading the same file skips processing (checksum cache)."
    },
    {
      "@id": "entity:target-curriculumImportPage.description-v1",
      "@type": "prov:Entity",
      "prov:value": "공식 州 학교 표준(TEKS, NGSS, Common Core 등)의 PDF 또는 CSV를 업로드하여 리뷰합니다. Ollama는 각 표준을 추출합니다. 전역 세트로 저장되면 모든 선생님과 집에서 학교하는 부모들은 이러한 표준으로 활동을 매핑할 수 있습니다. 같은 파일을 다시 업로드하면 처리를 건너뛰고(체크섬 캐시) 합니다.",
      "generated_by": {
        "@id": "activity:translation-curriculumImportPage.description-2026-07-06T08:55:53.468000+00:00"
      },
      "used_source": {
        "@id": "entity:source-curriculumImportPage.description"
      }
    },
    {
      "@id": "activity:translation-pages_donotsellpage.under_the_california_consumer_privacy_ac-2026-07-06T08:55:53.468000+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-06T08:55:53.468000+00:00",
